// Composición documental del asistente. Los campos solo viven en la propuesta.
function circuitOutline() {
  return `<svg class="circuit-outline" aria-hidden="true" viewBox="0 0 160 100" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"><path d="M8 84 34 49 56 41 84 40 94 34 106 16 135 8 144 13 129 34 123 65 114 70 84 72 56 76 39 74 13 90Z"/></svg>`;
}
function wizardContext() {
  const source = sources[state.combo];
  return `<div class="context-label">ESTRATEGIA</div><button class="context-current" data-action="start">Nueva estrategia</button><button class="context-link" data-view="revisions">Mis estrategias</button><div class="context-race"><div class="context-label">TU CARRERA</div>${[['helmet','Simulador','Le Mans Ultimate'],['car','Categoría',source.category],['target','Circuito',source.track]].map(([glyph,label,value])=>`<div class="context-combo">${glyph==='target'?circuitOutline():detailIcon(glyph)}<div><small>${label}</small><strong>${value}</strong></div></div>`).join('')}</div>`;
}
function wizardProgress() {
  return `<nav class="journey-progress" aria-label="Preparación"><ol>${['Inicio','Simulador','Evento','Coche y circuito','Reglas','Pilotos','Sesiones'].map((label,i)=>`<li class="${i<state.step?'done':''}"><button data-step="${i}" ${i>state.reached?'disabled':''} ${i===state.step?'aria-current="step"':''}><span>${i<state.step?'✓':i+1}</span><b>${label}</b></button></li>`).join('')}</ol></nav>`;
}
function wizardField(label,name,placeholder='Por confirmar',type='text') {
  return `<label class="wizard-field"><span>${label}</span><input name="${name}" type="${type}" ${type==='number'?`min="${name==='duration'?1:0}" step="any"`:''} value="${esc(state[name] || '')}" placeholder="${placeholder}" maxlength="120"></label>`;
}
function wizardSelect(label,name,values) {
  return `<label class="wizard-field"><span>${label}</span><select name="${name}">${values.map(v=>`<option ${state[name]===v?'selected':''}>${v}</option>`).join('')}</select></label>`;
}
function wizardChoice(key,value,title,description,glyph,disabled=false) {
  return `<button class="journey-choice" data-choice="${key}" data-value="${value}" aria-pressed="${state[key]===value}" ${disabled?'disabled':''}><i>${state[key]===value?'✓':'○'}</i>${glyph==='lmu'?'<b class="lmu-mark">LMU</b>':journeyIcon(glyph)}<span><strong>${title}</strong>${disabled?`<em class="chip">${key==='event'?'Sin conectar':'Próximamente'}</em>`:''}<small>${description}</small></span>${disabled?journeyIcon('lock'):''}</button>`;
}
function wizardScreen() {
  const source=sources[state.combo];
  const screens=[
    ['INICIO','Prepara tu próxima carrera','Elige cómo empezar. Construye tu estrategia con sesiones registradas.',`${wizardChoice('mode','manual','Manual','Configura el evento, el coche y el circuito. Después revisa tus datos.','document')}${wizardChoice('mode','auto','Automático','Parte de las sesiones disponibles para preparar tu carrera.','wand')}`],
    ['SIMULADOR','Elige el simulador','Elige el origen de la telemetría de tu próxima carrera.',`${wizardChoice('sim','lmu','Le Mans Ultimate','Prepara tu carrera con telemetría registrada.','lmu')}${wizardChoice('sim','future','Otros simuladores','Formatos propios para cada simulador.','platform',true)}`],
    ['EVENTO','Elige tu evento',state.mode==='manual'?'Configura una carrera personalizada o parte de un evento de Vantare.':'Prepara una carrera con las combinaciones disponibles en tus sesiones.',`${wizardChoice('event','custom','Carrera personalizada','Configura un evento a medida con las condiciones que desees.','calendar')}${wizardChoice('event','calendar','Calendario de Vantare','Aquí aparecerán los eventos compatibles de Vantare.','calendar',true)}${state.mode==='auto'?'<p class="journey-note">Muestra del banco de desarrollo. La búsqueda automática aún no está conectada.</p>':''}`],
    ['COCHE Y CIRCUITO','Elige tu combinación','Selecciona el simulador, la categoría y el circuito para continuar con tu plan de estrategia.',`<div class="combo-controls"><label><span>Simulador</span><div><b class="lmu-word">LMU</b><strong>Le Mans Ultimate</strong><span>⌄</span></div></label><label><span>Categoría</span><div>${detailIcon('car')}<strong>${source.category}</strong><span>⌄</span></div></label><label><span>Circuito</span><div class="circuit-select">${circuitOutline()}<select aria-label="Circuito" name="combo"><option value="imola" ${state.combo==='imola'?'selected':''}>Imola</option><option value="algarve" ${state.combo==='algarve'?'selected':''}>Algarve</option></select></div></label></div><section class="wizard-card circuit-card"><span class="eyebrow">INFORMACIÓN DEL CIRCUITO</span><div class="circuit-identity">${circuitOutline()}<div><h3>${source.track}</h3><p><span class="flag ${state.combo==='imola'?'it':'pt'}"></span>${state.combo==='imola'?'Italia':'Portugal'}</p></div></div><div class="circuit-meta"><span>${detailIcon('car')}${source.category}</span><span>${journeyIcon('bars')}Telemetría registrada</span></div><button class="orbit-btn orbit-btn--ghost change-circuit" data-action="change-circuit">${journeyIcon('swap')}Cambiar circuito</button></section>`],
    ['REGLAS','Configura tu carrera','Define las condiciones y parámetros de la carrera según el reglamento del evento.',`<div class="wizard-fields">${wizardField('Duración o distancia','duration','Por confirmar','number')}${wizardSelect('Formato','unit',['minutos','vueltas'])}${wizardSelect('Condiciones','weather',['Por confirmar','Seco','Mojado','Variables'])}${wizardField('Temperatura de pista · °C','temperature','Por confirmar','number')}</div><details class="wizard-card rule-card" open><summary>${detailIcon('fuel')}Combustible y energía virtual</summary><div class="rule-fields">${wizardField('Reserva de combustible · L','fuelReserve','Por confirmar','number')}${wizardField('Reserva de energía virtual · %','energyReserve','Por confirmar','number')}</div></details><details class="wizard-card rule-card"><summary>${detailIcon('tyre')}Neumáticos y paradas</summary><p>Compuestos, ventanas y simultaneidad según reglamento. Pendiente de conexión.</p></details><details class="wizard-card rule-card"><summary>${detailIcon('clock')}Límites de stint</summary><p>Tiempo máximo y relevos según el evento. Pendiente de conexión.</p></details>`],
    ['PILOTOS','Prepara tu equipo','Asigna tu piloto principal y configura los relevos de resistencia para tu plan de estrategia.',`<section class="wizard-card pilot-card"><span class="eyebrow">PILOTO PRINCIPAL</span><div class="pilot-search">${wizardField('Nombre del piloto','driver','Sin asignar')}${journeyIcon('search')}</div><div class="pilot-status"><div><small>Estado</small><p>${state.driver?'Asignado en el borrador':'● Sin asignar'}</p></div><div><small>Fuente de referencia</small><p><span class="chip">Ritmo por validar</span> ⓘ</p></div></div><button class="orbit-btn orbit-btn--primary add-pilot" disabled>+ Añadir piloto</button></section><details class="wizard-card relay-card" open><summary>RELEVOS DE RESISTENCIA</summary><p>El ritmo de otro piloto puede estimarse y ajustarse.</p><div class="relay-estimate"><span>Ritmo estimado</span><span class="chip">Estimación</span><input aria-label="Ritmo estimado · s/vuelta" name="estimatedPace" type="number" min="0" placeholder="Por confirmar" value="${esc(state.estimatedPace||'')}"></div></details>`],
    ['SESIONES','Elige tu telemetría','Selecciona una sesión compatible para cargar los datos de telemetría en tu plan de estrategia.',`<section class="wizard-card session-card"><h3>Sesiones compatibles</h3><div class="session-chips"><span class="chip"><b class="lmu-word">LMU</b></span><span class="chip">${circuitOutline()}${source.track}</span><span class="chip">${detailIcon('car')}${source.category}</span></div><div class="selected-session"><span class="selection-dot">✓</span><div><strong>${source.track} · ${source.date}</strong><p>${source.laps} vueltas registradas</p><span class="chip quality-badge">${journeyIcon('info')}Calidad pendiente de validar</span></div><button data-action="advanced">Ver observaciones ${journeyIcon('arrow')}</button></div>${state.combo==='algarve'?'<p class="journey-note">Grabación parcial · vueltas 101–171</p>':''}<hr><button class="orbit-btn orbit-btn--ghost search-session" disabled>${journeyIcon('search')}Buscar en otra ubicación</button><label class="copy-option"><input type="checkbox" name="copy" ${state.copy?'checked':''}><span>Guardar también una copia<small>Original intacto · copia aún sin conectar.</small></span></label></section>`],
  ];
  return screens[state.step];
}
function wizardPage() {
  const [kicker,title,intro,body]=wizardScreen();
  return `<div class="journey-page step-${state.step}">${wizardProgress()}<div class="journey-stage"><header class="journey-heading"><span class="eyebrow">${kicker}</span><h2 tabindex="-1">${title}</h2><p>${intro}</p></header><div class="journey-form">${body}</div></div><footer class="journey-footer"><span>${journeyIcon('check')}Originales intactos</span><div>${button('← Atrás','prev',false,state.step===0)}${button(state.step===6?'Abrir borrador →':'Continuar →','next',true)}</div></footer></div>`;
}
